import { Biome, LayerType, type WorldPointData } from "#types";
import { identifyBiome } from "@helpers/biomeResolver";

/**
 * Inverse of identifyBiome: pick a biome, get the layer values that produce it.
 *
 * The table below was generated by brute-forcing the whole
 * (elevation, rainfall, temperature, drainage) space against identifyBiome and
 * taking the median of every combination that yields each biome, separately for
 * coastal and inland tiles. Every entry is verified to round-trip.
 */

export type LayerValues = {
  elevation: number;
  rainfall: number;
  temperature: number;
  drainage: number;
};

type BiomeForms = { inland?: LayerValues; coast?: LayerValues };

