/**
 * Coast is decided by neighbouring tiles, not by the brush, so saltwater and
 * mangrove biomes are impossible inland and freshwater ones impossible on a
 * coast. Painting one swaps to its counterpart rather than silently failing.
 */
const COAST_SWAP: Partial<Record<Biome, Biome>> = {
  [Biome.SaltwaterTemperateMarsh]: Biome.FreshwaterTemperateMarsh,
  [Biome.FreshwaterTemperateMarsh]: Biome.SaltwaterTemperateMarsh,
  [Biome.SaltwaterTropicalMarsh]: Biome.FreshwaterTropicalMarsh,
  [Biome.FreshwaterTropicalMarsh]: Biome.SaltwaterTropicalMarsh,
  [Biome.SaltwaterTemperateSwamp]: Biome.FreshwaterTemperateSwamp,
  [Biome.FreshwaterTemperateSwamp]: Biome.SaltwaterTemperateSwamp,
  [Biome.SaltwaterTropicalSwamp]: Biome.FreshwaterTropicalSwamp,
  [Biome.FreshwaterTropicalSwamp]: Biome.SaltwaterTropicalSwamp,
  [Biome.MangroveSwamp]: Biome.FreshwaterTropicalSwamp,
};

/** The biome actually achievable at this tile, given whether it borders water. */
export function resolveVariant(target: Biome, coast: boolean): Biome {
  const forms = BIOME_TARGETS[target];
  if (forms && (coast ? forms.coast : forms.inland)) return target;
  const swap = COAST_SWAP[target];
  if (swap) {
    const alt = BIOME_TARGETS[swap];
    if (alt && (coast ? alt.coast : alt.inland)) return swap;
  }
  return target;
}

export const LAYER_OF: Record<keyof LayerValues, LayerType> = {
  elevation: LayerType.Elevation,
  rainfall: LayerType.Rainfall,
  temperature: LayerType.Temperature,
  drainage: LayerType.Drainage,
};

const KEYS: Array<keyof LayerValues> = [
  "elevation",
  "rainfall",
  "temperature",
  "drainage",
];

/**
 * Minimal edit: start from the representative, then hand back every value the
 * tile already has that is still compatible with the target. Painting forest
 * onto a hillside keeps the hillside.
 */
export function solveForBiome(
  target: Biome,
  current: WorldPointData,
  coast: boolean,
  locked?: Partial<Record<LayerType, boolean>>,
): LayerValues | null {
  const variant = resolveVariant(target, coast);
  const forms = BIOME_TARGETS[variant];
  const rep = forms && (coast ? forms.coast : forms.inland);
  if (!rep) return null;

  const out: LayerValues = { ...rep };

  // Locked layers win outright. The result may then miss the requested biome —
  // that is the honest outcome, and the caller can show what was actually made.
  for (const key of KEYS) {
    if (locked?.[LAYER_OF[key]]) out[key] = current[key];
  }

  for (const key of KEYS) {
    if (locked?.[LAYER_OF[key]]) continue;
    const trial: LayerValues = { ...out, [key]: current[key] };
    if (identifyBiome(trial as unknown as WorldPointData, coast) === variant) {
      out[key] = current[key];
    }
  }
  return out;
}

/**
 * Nudge values without leaving the biome, so painted regions have texture
 * instead of reading as a flat stamp. Reverts any nudge that would reclassify.
 */
export function jitterWithinBiome(
  values: LayerValues,
  coast: boolean,
  amount: number,
  rand: () => number,
): LayerValues {
  const biome = identifyBiome(values as unknown as WorldPointData, coast);
  const out: LayerValues = { ...values };
  for (const key of KEYS) {
    const span = key === "elevation" ? amount * 3 : amount;
    const delta = Math.round((rand() * 2 - 1) * span);
    if (!delta) continue;
    const trial: LayerValues = { ...out, [key]: out[key] + delta };
    if (identifyBiome(trial as unknown as WorldPointData, coast) === biome) {
      out[key] = trial[key];
    }
  }
  return out;
}


